"""Authentication endpoints: register, login, refresh, me."""
from flask import current_app, jsonify, request
from flask_jwt_extended import (
    create_access_token,
    create_refresh_token,
    get_jwt_identity,
    jwt_required,
)

from ...audit import audit
from ...errors import ConflictError, UnauthorizedError
from ...extensions import db, limiter
from ...models import User
from ...schemas import LoginSchema, RegisterSchema
from . import bp

_register_schema = RegisterSchema()
_login_schema = LoginSchema()


def _auth_limit():
    return current_app.config["RATELIMIT_AUTH"]


@bp.post("/auth/register")
@limiter.limit(_auth_limit)
def register():
    data = _register_schema.load(request.get_json(silent=True) or {})
    email = data["email"].lower().strip()

    if User.query.filter_by(email=email).first():
        raise ConflictError("A user with this email already exists.")

    user = User(email=email)
    user.set_password(data["password"])
    db.session.add(user)
    db.session.flush()  # assign user.id for the audit entry
    audit("user.register", "user", user.id, user_id=user.id)
    db.session.commit()

    return jsonify({"data": user.to_dict()}), 201


@bp.post("/auth/login")
@limiter.limit(_auth_limit)
def login():
    data = _login_schema.load(request.get_json(silent=True) or {})
    email = data["email"].lower().strip()

    user = User.query.filter_by(email=email).first()
    if user is None or not user.check_password(data["password"]):
        audit("user.login_failed", "user", detail={"email": email})
        db.session.commit()
        raise UnauthorizedError("Invalid email or password.")
    if not user.is_active:
        raise UnauthorizedError("Account is disabled.")

    identity = str(user.id)
    access = create_access_token(identity=identity)
    refresh = create_refresh_token(identity=identity)
    audit("user.login", "user", user.id, user_id=user.id)
    db.session.commit()

    return jsonify(
        {
            "data": {
                "access_token": access,
                "refresh_token": refresh,
                "token_type": "Bearer",
            }
        }
    )


@bp.post("/auth/refresh")
@jwt_required(refresh=True)
def refresh():
    user_id = int(get_jwt_identity())
    access = create_access_token(identity=str(user_id))
    audit("user.token_refresh", "user", user_id, user_id=user_id)
    db.session.commit()
    return jsonify({"data": {"access_token": access, "token_type": "Bearer"}})


@bp.get("/auth/me")
@jwt_required()
def me():
    user = db.session.get(User, int(get_jwt_identity()))
    if user is None:
        raise UnauthorizedError("User no longer exists.")
    return jsonify({"data": user.to_dict()})

"""Item resource: authenticated CRUD with validation and pagination."""
from flask import jsonify, request
from flask_jwt_extended import get_jwt_identity, jwt_required

from ...audit import audit
from ...errors import NotFoundError
from ...extensions import db
from ...models import Item
from ...pagination import paginate
from ...schemas import ItemCreateSchema, ItemUpdateSchema
from . import bp

_create_schema = ItemCreateSchema()
_update_schema = ItemUpdateSchema()


def _current_user_id() -> int:
    return int(get_jwt_identity())


def _get_owned_item(item_id: int) -> Item:
    item = db.session.get(Item, item_id)
    if item is None or item.owner_id != _current_user_id():
        # 404 (not 403) so we don't leak existence of others' resources
        raise NotFoundError("Item not found.")
    return item


@bp.get("/items")
@jwt_required()
def list_items():
    query = (
        Item.query.filter_by(owner_id=_current_user_id())
        .order_by(Item.id.asc())
    )
    return jsonify(paginate(query))


@bp.post("/items")
@jwt_required()
def create_item():
    data = _create_schema.load(request.get_json(silent=True) or {})
    user_id = _current_user_id()
    item = Item(owner_id=user_id, **data)
    db.session.add(item)
    db.session.flush()
    audit("item.create", "item", item.id, user_id=user_id)
    db.session.commit()
    return jsonify({"data": item.to_dict()}), 201


@bp.get("/items/<int:item_id>")
@jwt_required()
def get_item(item_id):
    item = _get_owned_item(item_id)
    return jsonify({"data": item.to_dict()})


@bp.patch("/items/<int:item_id>")
@jwt_required()
def update_item(item_id):
    item = _get_owned_item(item_id)
    data = _update_schema.load(request.get_json(silent=True) or {})
    for key, value in data.items():
        setattr(item, key, value)
    audit(
        "item.update",
        "item",
        item.id,
        user_id=_current_user_id(),
        detail={"fields": sorted(data.keys())},
    )
    db.session.commit()
    return jsonify({"data": item.to_dict()})


@bp.delete("/items/<int:item_id>")
@jwt_required()
def delete_item(item_id):
    item = _get_owned_item(item_id)
    db.session.delete(item)
    audit("item.delete", "item", item_id, user_id=_current_user_id())
    db.session.commit()
    return "", 204

"""Application factory."""
from flask import jsonify

from .config import CONFIGS
from .errors import error_response, register_error_handlers
from .extensions import db, jwt, limiter


def create_app(config_name="dev", config_overrides=None):
    from flask import Flask

    app = Flask(__name__)
    app.config.from_object(CONFIGS[config_name])
    if config_overrides:
        app.config.update(config_overrides)

    # Extensions
    db.init_app(app)
    jwt.init_app(app)
    limiter.init_app(app)
    limiter._default_limits.clear()  # reset between app instances (tests)
    limiter.limit(app.config["RATELIMIT_DEFAULT"])(_noop)  # no-op keeper

    # Blueprints (versioned APIs)
    from .api.v1 import bp as api_v1_bp

    limiter.limit(app.config["RATELIMIT_DEFAULT"])(api_v1_bp)
    app.register_blueprint(api_v1_bp)

    # Error handling
    register_error_handlers(app)
    _register_jwt_error_handlers()

    # Models must be imported before create_all
    from . import models  # noqa: F401

    with app.app_context():
        db.create_all()

    @app.get("/health")
    @limiter.exempt
    def health():
        return jsonify({"status": "ok"})

    return app


def _noop():  # pragma: no cover
    pass


def _register_jwt_error_handlers():
    """Make flask-jwt-extended errors use the standard error envelope."""

    @jwt.unauthorized_loader
    def missing_token(reason):
        return error_response(401, "unauthorized", reason)

    @jwt.invalid_token_loader
    def invalid_token(reason):
        return error_response(401, "invalid_token", reason)

    @jwt.expired_token_loader
    def expired_token(jwt_header, jwt_payload):
        return error_response(401, "token_expired", "Token has expired.")

    @jwt.revoked_token_loader
    def revoked_token(jwt_header, jwt_payload):
        return error_response(401, "token_revoked", "Token has been revoked.")

